


































import { Component, BaseVueComponent, Getter, State, Action } from "sunway-vue";
import CollapsePanel from "../collapsePanel/CollapsePanel.vue";
import TextEditor from "@/com/sunwayworld/components/editor/TextEditor.vue";
import NumberEditor from "@/com/sunwayworld/components/editor/NumberEditor.vue";
import ChooseEditor from "@/com/sunwayworld/components/editor/ChooseEditor.vue";
import SelectEditor from "@/com/sunwayworld/components/editor/select/SelectEditor.vue";
import { ColumnEditor, ColumnEvent, GridColumnVue } from "../../interface/GridInterface";
import { ColumnChangeOption } from "@/com/sunwayworld/components/grid/interface/ColumnAttrEditor";

@Component({
    components: { CollapsePanel, TextEditor, NumberEditor, ChooseEditor, SelectEditor }
})
export default class FieldSettingPanle extends BaseVueComponent<GeneralObject> {
    @Getter("activeColumnEditorAttrs")
    private attributeList!: ColumnEditor[];

    @State("activeColumnEditorEvents")
    private events!: ColumnEvent[];

    @State
    private activeColumn?: GridColumnVue;

    get attributes(): ColumnEditor[] {
        return this.attributeList;
    }

    @Action
    private updateColumnAttr!: (attr: ColumnChangeOption) => void;

    private getAttributeKey(attribute: ColumnEditor) {
        if (!this.activeColumn) {
            return;
        }
        let pre = this.activeColumn.field;
        if (this.activeColumn.checkbox) {
            pre = "checkbox";
        }
        if (this.activeColumn.radio) {
            pre = "radio";
        }
        if (this.activeColumn.index) {
            pre = "index";
        }
        return pre + attribute.attribute;
    }
}
