

















import { Vue, Component, State, Mutation, Action } from "sunway-vue";
import ColumnsDesginContainer from "./desginContainer/ColumnsDesignContainer.vue";

@Component({
    components: {
        ColumnsDesginContainer
    }
})
export default class ColumnsDesignBox extends Vue {
    @Mutation
    saveColumns!: Function;

    @Action
    private updateGridColumns!: () => void;

    @State
    gridInstance!: Gikam.component.Grid;

    private show = true;

    private async confirmHandle() {
        await this.updateGridColumns();
        this.$emit("confirmUpdateColumns", this.gridInstance);
        this.cancelHandle();
    }

    @State
    private comp!: Gikam.component.Grid;

    private cancelHandle(): void {
        this.show = false;
        this.$nextTick(() => {
            this.$destroy();
        });
    }
}
