





















































import { Component, BaseVueComponent, State, Action } from "sunway-vue";
import ToolbarButton from "./ToolbarButton.vue";
import SaveImg from "@/com/sunwayworld/components/img/SaveImg.vue";
import PlusImg from "@/com/sunwayworld/components/img/PlusImg.vue";
import ForkImg from "@/com/sunwayworld/components/img/ForkImg.vue";
import ColumnsTree from "./ColumnsTree.vue";
import MoveDownImg from "@/com/sunwayworld/components/img/MoveDownImg.vue";
import MoveUpImg from "@/com/sunwayworld/components/img/MoveUpImg.vue";
import ColumnSettingPanle from "../column/columnSettingPanel.vue";

@Component({
    components: { ToolbarButton, SaveImg, ColumnsTree, PlusImg, ForkImg, MoveDownImg, MoveUpImg, ColumnSettingPanle }
})
export default class ColumnsDesignContainer extends BaseVueComponent<GeneralObject> {
    @State("comp")
    private gridInstance!: Gikam.component.Grid;

    get gridColumns() {
        return this.gridInstance.store.state.columns;
    }

    @Action
    private moveColumnUp!: Function;

    @Action
    private moveColumnDown!: Function;

    @Action
    private insertColumn!: Function;

    @Action
    private removeColumn!: Function;
}
