










import { BaseVueComponent, Component, Action } from "sunway-vue";
import TreeRootNodeImg from "@/com/sunwayworld/components/img/TreeRootNodeImg.vue";
import { GridColumn } from "../../interface/GridInterface";
import TreeMinusImg from "@/com/sunwayworld/components/img/TreeMinusImg.vue";
import TreePlusImg from "@/com/sunwayworld/components/img/TreePlusImg.vue";

interface Props {
    column: GridColumn;
}

@Component({
    components: {
        TreeMinusImg,
        TreePlusImg,
        TreeRootNodeImg
    }
})
export default class ColumnTreeNode extends BaseVueComponent<Props> {
    column: GridColumn = this.props.column;

    @Action
    activeColumn!: (column: GridColumn) => void;

    nodeClickHandle() {
        this.$emit("nodeClick");
        this.$set(this.column, "active", true);
        this.activeColumn(this.column);
    }

    getActiveNodeClass() {
        return {};
    }

    propI18N(text: string): string {
        return Gikam.propI18N(text);
    }

    private mounted() {
        if (this.column.active) {
            this.nodeClickHandle();
        }
    }
}
