































import { Component, State, BaseVueComponent } from "sunway-vue";
import TreeRootNodeImg from "@/com/sunwayworld/components/img/TreeRootNodeImg.vue";
import { GridColumn } from "@/com/sunwayworld/components/grid/interface/GridInterface";
import ColumnTreeNode from "./ColumnTreeNode.vue";
import TreeMinusImg from "@/com/sunwayworld/components/img/TreeMinusImg.vue";
import TreePlusImg from "@/com/sunwayworld/components/img/TreePlusImg.vue";

@Component({
    components: {
        TreeRootNodeImg,
        ColumnTreeNode,
        TreeMinusImg,
        TreePlusImg
    }
})
export default class ColumnsTree extends BaseVueComponent<GeneralObject> {
    private expand = true;

    @State("tempColumns")
    columns!: GridColumn[];

    @State
    gridInstance!: Gikam.component.Grid;

    get gridId(): string {
        return this.gridInstance.options.id || "";
    }

    switchClickHandle(): void {
        this.expand = !this.expand;
    }

    getColumnKey(column: GridColumn) {
        if (column.radio) {
            return "radioColumn";
        }
        if (column.checkbox) {
            return "checkboxColumn";
        }
        if (column.index) {
            return "index";
        }
        return column.field;
    }
}
